#!/usr/bin/env python3
from pathlib import Path
import json,gzip,copy
from shapely.geometry import shape,box,Point
from shapely.ops import unary_union,polygonize
P=Path(__file__).resolve().parent;C=P.parent/'contexts'
with gzip.open(P/'source-objects.geojson.gz','rt',encoding='utf-8') as h:objects={f['id']:f for f in json.load(h)['features']}
r=json.load(open(P/'recipes.json'));tasks=json.load(open(P/'assignment.json'))['municipalities'];city={c['municipality']:c for c in tasks};cache={}
def load(c,kind):
 key=(c,kind)
 if key not in cache:
  path=C/city[c]['contextKey']/(kind+'.geojson'+('.gz' if kind in ['areas','roads','addresses'] else ''))
  cache[key]=json.load(gzip.open(path,'rt') if path.suffix=='.gz' else open(path))['features']
 return cache[key]
def retain(c,kind,f):
 f=copy.deepcopy(f);f['properties']['originalId']=f.get('id');f['id']=city[c]['contextKey']+':'+kind+':'+str(f.get('id') or f['properties'].get('name'));objects[f['id']]=f;return f['id']
def get(c,kind,pred,scope=None):
 return [retain(c,kind,f) for f in load(c,kind) if pred(f) and (not scope or shape(f['geometry']).intersects(box(*scope)))]
def street(c,n,ns,url,note,ev,b=None,allow=45,idsExtra=None,partial=False):
 if any(x['municipality']==c and x['name']==n for x in r):return
 ids=get(c,'roads',lambda f:f['properties']['name'] in ns,b)+(idsExtra or []);assert ids
 mun=load(c,'municipality')[0]['geometry']
 r.append(dict(batch='batch-04',municipality=c,name=n,operation='street-envelope',inputIds=ids,inputScopes={i:b for i in ids if ':roads:' in i} if b else {},clipGeometry=mun,sourceUrl=url,supportingUrls=list(dict.fromkeys(objects[i]['properties']['source']['url'] for i in ids)),evidenceFiles=['evidence/'+ev],partialFootprint=partial,frontageAllowanceM=allow,approximationNote=note+' The actual road/surface extent forms a convex whole occupied-tract envelope with an explicit inferred '+str(allow)+' m outer plot/verge allowance. Long-street scopes are source-segment selection only, not a point-centred output box. Outer joins and locality extremities remain low confidence.'))
street('Szentgotthárd','Ipari park',['Haris út','Haris','Füzesi út'],'https://szentgotthard.hu/hu/ipari-park.html','The municipality describes the cross-border industrial park north of the Rába and its Füzesi approach. The full industrial Haris access network and local Füzesi frontage span the larger industrial quarter around the separately retained park label, including multiple factory plots rather than a single factory/cell. Planned expansion land and the exact park-company perimeter are not established.','first-primary-search.json',[16.2745,46.9574,16.2950,46.9700],55)
zsida=get('Szentgotthárd','roads',lambda f:f['id'] in ['osm:way:238289790','osm:way:304870423','osm:way:304870424','osm:way:575654722'])
street('Szentgotthárd','Zsidahegy',[],'https://hivatal.szentgotthard.hu/hirdetmenyek/varosuzemeltetesi-hirdetmenyek/hulladekgazdalkodassal-kapcsolatos-hirdetmenyek-2/hazhoz-meno-szelektiv-hulladekgyujtes.html','The municipality explicitly defines Zsidahegy through Zsidahegyi/Apátistvánfalvai streets and its bus-turning approach. The four original residential road ways actually spanning the detached hillside settlement are unnamed in OSM; their geometry was inspected around the saved quarter and municipal access descriptions. Their source tags are residential, not invented label spokes. Exact assignment of individual unnamed source ways to the municipal street names is inferred.','final-west-identity-search.json',allow=60,idsExtra=zsida)
street('Sopron','Brandmajor',['Gida patak utca','Hasfalvi utca'],'https://www.brandmajor.hu/kapcsolat/','The local farm operator gives Brandmajor as its Gida patak street address, and the archived quarter street inventory also names Hasfalvi. The actual local residential/farm access network estimates the occupied compound and plots. The broader historic Brandmajor agricultural estate is not established, so this is a partial occupied-locality footprint.','final-street-associations.json',[16.5880,47.6480,16.5970,47.6532],45,partial=True)
street('Sopron','Óbrennberg',['Óbrennbergi út','Kórház telep'],'https://www.visitsopron.com/hu/reszletek/hatarfa-emlektura','The official regional tour description distinguishes the Kórház/Óbrennberg localities along the old mining valley. The archived Óbrennberg street associations identify Kórház telep and Óbrennbergi road. Their real local residential/forest-edge circuit estimates the occupied old mining quarter, not the unrelated woodland-only candidate east of the label.','final-street-associations.json',[16.4945,47.6485,16.5055,47.6572],55)
street('Letenye','Egyeduta',['Rákóczi Ferenc utca','Temesvári utca','Eötvös utca','Petőfi Sándor utca','Szent Imre herceg utca'],'https://www.letenye.hu/images/Athelyezett/KEZDOOLDAL/ITS_letenye_2015/ITS_letenye_megalapozo_vizsgalat.pdf','The municipal ITS explicitly calls the eastern old quarter Egyeduta, with Szent Imre street and its southern continuation as the west boundary and the built-up edge outside. The actual southeastern Rákóczi/Temesvári/Eötvös grid supplies a broad occupied-quarter interpretation east of that divider. Local source-street scopes infer the current built-up outer ends; this is not unseen municipal map digitization.','letenye-eastern-boundary-text.json',[16.7345,46.4155,16.7605,46.4259],55)
street('Sárvár','Vadkert',['Vadkert körút'],'https://njt.jog.gov.hu/jogszabaly/2016-37-SP-5Y3245.8','Municipal heritage/address descriptions identify Vadkert major and the Vadkert circuit, including the estate stables/lodging. The complete original named circuit spans the larger park/estate/resort quarter around the retained name, rather than only the restaurant building or a small road cell. The exact historical major perimeter remains uncertain.','rural-west-search.json',allow=55)
street('Barcs','Drávaszentes',['Fő utca','Tarnócai utca','Malom utca'],'https://www.barcs.hu/index.php/barcsrol/telepulesreszek','The municipality identifies Drávaszentes as the former separate village incorporated in 1979. The actually opened quarter inventory identifies Fő, Tarnócai and Malom streets. Their full local village sections estimate the whole detached inhabited cluster, not the church/park core; outer farm-field territory is not established.','remaining-urban-street-indexes.json',[17.4080,45.9890,17.4350,46.0070],65)
street('Buzsák','Szent István-telep',['Dózsa György út','Ciframalom utca'],'https://utcak-magyarorszag.openalfa.com/szent-istvan-telep','The archived quarter identity and local address/map evidence locate Szent István-telep on the eastern Dózsa corridor. The reviewed local Dózsa/Ciframalom road frontage, between the northern residential junction and the southern mill branch, estimates this inhabited strip rather than assigning the whole Buzsák residential parent. The old quarter termini remain uncertain.','remaining-urban-street-indexes.json',[17.5880,46.6320,17.5950,46.6412],60)
street('Győr','Koldustelek',['Sármány utca','Pacsirta utca','Fülemüle utca','Fecske utca','Pozsonyi út'],'https://vamosszabadi.hu/wp-content/uploads/2019/09/V%C3%A1mosszabadi-hattan2019.pdf','The primary heritage study identifies Kisbácsa-Koldustelek at the northwest edge of Kisbácsa, with Pozsonyi road and the municipal border as context. The reviewed actual Sármány/Pacsirta/Fülemüle/Fecske grid and the local Pozsonyi divider estimate the historic tract as now occupied residential blocks. No identity with the neighboring Szitásdomb quarter is asserted; historical extents can overlap.','gyor-cserszeg-search.json',[17.6390,47.7192,17.6510,47.7270],45)
# Two coherent physical field circuits need full native footpath connectivity;
# Katona also uses the real municipality edge as an explicit inferred outer limit.
for c,n,usecity,url,note in [
 ('Győr','Katona-rét',True,'https://magyarnemzetinevter.hu/foldrajzi-nevter/?date=2026-09-16&id=482733','The national geographic-name index and original OSM label identify Katona-rét on the floodplain. The reviewed coherent tract is bounded by actual Ikrény-Pásdombi and northern channel/track geometry. Its western outside limit uses the real Győr municipality edge as a clearly inferred tract closure; this is not a published Katona boundary or an arbitrary municipality remainder.'),
 ('Magyaregres','Jegyző-föld',False,'https://www.openstreetmap.org/node/8398362323','The original Jegyző-föld name lies in the southern field east of Magyaregres. Actual surveyed access tracks, native footpath links and field edges enclose the reviewed coherent agricultural tract. This uses native physical continuity, with no synthetic point circle or connector lines.')]:
 if any(x['municipality']==c and x['name']==n for x in r):continue
 sources=[('roads',f,shape(f['geometry'])) for f in load(c,'roads')]
 sources += [('areas',f,shape(f['geometry']).boundary) for f in load(c,'areas') if f['properties']['tags'].get('natural')!='mountain_range']
 if usecity:sources += [('municipality',f,shape(f['geometry']).boundary) for f in load(c,'municipality')]
 t=next(t for t in city[c]['targets'] if t['name']==n);pt=t['pointCandidates'][0]['coordinates'];gs=[g for g in polygonize(unary_union([g for _,_,g in sources])) if g.covers(Point(pt))];g=min(gs,key=lambda g:g.area)
 ids=[retain(c,kind,f) for kind,f,line in sources if line.distance(g.boundary)<1e-10]
 r.append(dict(batch='batch-04',municipality=c,name=n,operation='physical-circuit',inputIds=ids,sourceNameAssociationPoint=pt,sourceUrl=url,supportingUrls=list(dict.fromkeys(objects[i]['properties']['source']['url'] for i in ids)),evidenceFiles=['evidence/final-rural-primary-search.json','review-maps/'+city[c]['contextKey']+'-'+str(city[c]['targets'].index(t))+'.png'],partialFootprint=True,approximationNote=note+' It is explicitly a low-confidence partial physical tract because the full historical named-field perimeter is not independently established.'))
street('Szigetvár','Turbék',['Turbéki dűlő','Drahos Andrea út','Janicsár dűlő','Aga dűlő','Török dűlő','Pasa dűlő','Kalifa dűlő','Zsibóti út'],'https://njt.jog.gov.hu/jogszabaly/2022-9-SP-5Y2392','Official electoral/planning text names Turbék puszta and the local municipal street inventory preserves the Turbéki/garden-road names. The actual connected Turbéki/Drahos and nearby Ottoman-named garden grid around the historical place label estimates the whole occupied hill-side locality, not just its chapel or a triangular field cell. The connection of the broader garden grid to the historic puszta usage is an explicit spatial inference.','eastern-shard-search.json',[17.8265,46.0668,17.8495,46.0790],55)
diosareas=get('Balatonszárszó','areas',lambda f:f['id'] in ['osm:way:165358331','osm:way:165358335'])
street('Balatonszárszó','Diós',['Szóládi utca'],'https://utcak-magyarorszag.openalfa.com/utcak/szoladi-utca-dios-balatonszarszo','The actually retrieved named-quarter street source associates the local Szóládi street/cemetery approach with Diós. The adjacent whole original vineyard block and smaller vineyard parcel provide a meaningful occupied hillside/field footprint. Their native geometry and the local street frontage are combined rather than accepting a spurious long motorway-edge field circuit. The larger historical locality is unresolved, so this is explicitly a partial source-footprint estimate.','final-rural-primary-search.json',[17.8373,46.8104,17.8445,46.8170],40,idsExtra=diosareas,partial=True)
(P/'recipes.json').write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n');(P/'source-objects.geojson.gz').write_bytes(gzip.compress(json.dumps(dict(type='FeatureCollection',features=list(objects.values())),ensure_ascii=False,separators=(',',':')).encode(),mtime=0));print(len(r),'recipes')
